// заливка без рекурсии: глубина не ограничена стеком потока
void Fill(int[,] grid, int sx, int sy, int color) {
    int from = grid[sx, sy];
    if (from == color) return;
    var stack = new Stack<(int x, int y)>();
    stack.Push((sx, sy));
    while (stack.Count > 0) {
        var (x, y) = stack.Pop();
        if (x < 0 || y < 0 || x >= grid.GetLength(0) || y >= grid.GetLength(1)) continue;
        if (grid[x, y] != from) continue;
        grid[x, y] = color;
        stack.Push((x + 1, y)); stack.Push((x - 1, y));
        stack.Push((x, y + 1)); stack.Push((x, y - 1));
    }
}

