int LowerBound(int[] a, int x) {
    int lo = 0, hi = a.Length;           // hi не входит
    while (lo < hi) {                    // пусто, когда lo == hi
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < x) lo = mid + 1;    // a[mid] мал — он не ответ
        else hi = mid;                   // a[mid] подходит — ответ не правее
    }
    return lo;                           // a.Length, если такого нет
}

