// концы отрезков — любые int, в том числе отрицательные
int[][] Merge(int[][] iv) {
    Array.Sort(iv, (x, y) =>
        x[0] - y[0]);
    var res = new List<int[]>();
    foreach (var cur in iv) {
        int n = res.Count;
        if (n > 0 && res[n - 1][1] >= cur[0])
            res[n - 1][1] = Math.Max(res[n - 1][1], cur[1]);
        else res.Add(cur);
    }
    return res.ToArray();
}

