public int[] ProductExceptSelf(int[] nums) {
    int n = nums.Length;
    var ans = new int[n];
    int prefix = 1;                          // произведение nums[0..i-1]
    for (int i = 0; i < n; i++) {
        ans[i] = prefix;
        prefix *= nums[i];
    }
    int suffix = 1;                          // произведение nums[i+1..n-1]
    for (int i = n - 1; i >= 0; i--) {
