public int Trap(int[] h) {
    var st = new Stack<int>();               // индексы, высоты не возрастают
    int total = 0;
    for (int i = 0; i < h.Length; i++) {
        while (st.Count > 0 && h[i] > h[st.Peek()]) {
            int bottom = st.Pop();
            if (st.Count == 0) break;        // слева нет стены — вода стекает
            int left = st.Peek();
            int width = i - left - 1;
            total += (Math.Min(h[left], h[i]) - h[bottom]) * width;
        }
        st.Push(i);
    }
    return total;
}

