public bool IsValid(string s) {
    if (s.Length % 2 == 1) return false;            // пару найдут не все
    var pairs = new Dictionary<char, char> { [')'] = '(', [']'] = '[', ['}'] = '{' };
    var stack = new Stack<char>();
    foreach (char c in s) {
        if (!pairs.TryGetValue(c, out char open)) stack.Push(c);       // открывающая
        else if (stack.Count == 0 || stack.Pop() != open) return false; // закрывающая
    }
    return stack.Count == 0;                         // всё ли закрыто
}

