    var left = LowestCommonAncestor(root.left, p, q);
    var right = LowestCommonAncestor(root.right, p, q);
    if (left != null && right != null) return root;   // p и q расходятся здесь
    return left ?? right;                             // передать находку наверх
}

// [-10, 9, 20, null, null, 15, 7], post-order: 9, 15, 7, 20, -10
// 9:   поворот 9 → best 9,   вверх 9
// 15:  поворот 15 → best 15, вверх 15      7: вверх 7
// 20:  поворот 15 + 20 + 7 = 42 → best 42, вверх 20 + 15 = 35
// -10: поворот 9 − 10 + 35 = 34 < 42,      вверх −10 + 35 = 25
// ответ — best = 42, а не 25

private int best;

public int MaxPathSum(TreeNode root) {
    best = ___;
    Gain(root);
    return best;
}

private int Gain(TreeNode node) {
    if (node == null) return 0;
    int left = Math.Max(___, Gain(node.left));
    int right = Math.Max(0, Gain(node.right));
    best = Math.Max(best, ___);
    return ___;
}

private int best = 0;

public int MaxPathSum(TreeNode root) { Gain(root); return best; }

private int Gain(TreeNode node) {
    if (node == null) return 0;
    int left = Math.Max(0, Gain(node.left));
    int right = Math.Max(0, Gain(node.right));
    best = Math.Max(best, node.val + left + right);
    return node.val + Math.Max(left, right);
}

static int Depth(Transform t) {
    int d = 0;
    for (; t != null; t = t.parent) d++;
    return d;
}

static Transform CommonParent(Transform a, Transform b) {
    int da = Depth(a), db = Depth(b);
    for (; da > db; da--) a = a.parent;     // выровнять глубины
    for (; db > da; db--) b = b.parent;
    while (a != b) { a = a.parent; b = b.parent; }
    return a;                               // null — у объектов разные корни
}

public TreeNode Lca(TreeNode root, TreeNode p, TreeNode q) {
    var parent = new Dictionary<TreeNode, TreeNode> { [root] = null };
    var stack = new Stack<TreeNode>();
    stack.Push(root);
    while (!parent.ContainsKey(p) || !parent.ContainsKey(q)) {
        var node = stack.Pop();
        if (node.left != null) { parent[node.left] = node; stack.Push(node.left); }
        if (node.right != null) { parent[node.right] = node; stack.Push(node.right); }
    }
    var ancestors = new HashSet<TreeNode>();
    for (var x = p; x != null; x = parent[x]) ancestors.Add(x);
    var y = q;
    while (!ancestors.Contains(y)) y = parent[y];
    return y;
}

private int k, ans;

public int KthSmallest(TreeNode root, int k) { this.k = k; Walk(root); return ans; }

private void Walk(TreeNode node) {
    if (node == null || k == 0) return;
    if (--k == 0) { ans = node.val; return; }
    Walk(node.left);
    Walk(node.right);
}
